/* prog53_dfs_cycle – reproduced from the analysed binary
 *
 * The original program expects its command‑line arguments to describe a
 * directed graph with at most 8 vertices (numbered 0 … 7).  The arguments
 * are given as a sequence of integer pairs  u v  representing an edge
 * from vertex u to vertex v.
 *
 *   prog53_dfs_cycle u1 v1 u2 v2 … uk vk
 *
 * The number of arguments (excluding the program name) must be even;
 * otherwise the program prints "INVALID_INPUT".
 *
 * Every vertex index must be in the range [0,7]; any out‑of‑range value
 * also causes "INVALID_INPUT".
 *
 * After the input has been validated the program builds the adjacency
 * matrix of the directed graph and runs a depth‑first search to decide
 * whether the graph contains a directed cycle.
 *
 *   * If a cycle is found the program prints "CYCLE".
 *   * If the graph is acyclic the program prints "ACYCLIC".
 *
 * The output is produced with a single call to `puts`, exactly as the
 * original binary does.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXV 8                     /* maximum number of vertices */

/* adjacency matrix: adj[u][v] == 1  ⇔  edge u → v exists */
static int adj[MAXV][MAXV];

/* colour array used by DFS:
 *   0 – not visited,
 *   1 – currently on recursion stack (grey),
 *   2 – completely processed (black)
 */
static int colour[MAXV];

static bool found_cycle = false;

/* depth‑first search that stops as soon as a cycle is discovered */
static void dfs(int u)
{
    if (found_cycle)               /* early exit if a cycle is already known */
        return;

    colour[u] = 1;                 /* mark as grey (in recursion stack) */

    for (int v = 0; v < MAXV; ++v) {
        if (!adj[u][v])            /* no edge u → v */
            continue;

        if (colour[v] == 0) {     /* tree edge */
            dfs(v);
            if (found_cycle)      /* propagate early exit */
                return;
        } else if (colour[v] == 1) {
            /* back edge → cycle */
            found_cycle = true;
            return;
        }
        /* colour[v] == 2 : cross/forward edge – nothing to do */
    }

    colour[u] = 2;                 /* mark as black (finished) */
}

/* --------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
     *  1.  Input validation
     * ----------------------------------------------------------------- */
    if ((argc - 1) % 2 != 0) {                 /* need an even number of ints */
        puts("INVALID_INPUT");
        return 0;
    }

    int edge_cnt = (argc - 1) / 2;             /* number of (u,v) pairs */

    /* initialise adjacency matrix and colour array */
    memset(adj, 0, sizeof(adj));
    memset(colour, 0, sizeof(colour));
    found_cycle = false;

    for (int i = 0; i < edge_cnt; ++i) {
        char *endptr;
        long u = strtol(argv[1 + 2 * i], &endptr, 10);
        if (*endptr != '\0') {                 /* non‑numeric input */
            puts("INVALID_INPUT");
            return 0;
        }
        long v = strtol(argv[2 + 2 * i], &endptr, 10);
        if (*endptr != '\0') {
            puts("INVALID_INPUT");
            return 0;
        }

        if (u < 0 || u >= MAXV || v < 0 || v >= MAXV) {
            puts("INVALID_INPUT");
            return 0;
        }

        adj[(int)u][(int)v] = 1;               /* store the directed edge */
    }

    /* -----------------------------------------------------------------
     *  2.  Cycle detection (DFS from every unvisited vertex)
     * ----------------------------------------------------------------- */
    for (int v = 0; v < MAXV && !found_cycle; ++v) {
        if (colour[v] == 0)
            dfs(v);
    }

    /* -----------------------------------------------------------------
     *  3.  Output result
     * ----------------------------------------------------------------- */
    if (found_cycle)
        puts("CYCLE");
    else
        puts("ACYCLIC");

    return 0;
}
